// 1. Беремо весь вхідний масив з ноду Extract from File.json
const rawData = $input.all()[0].json.data;

if (!rawData || !Array.isArray(rawData)) {
    return [{ json: { pageContent: "Помилка: Масив даних відсутній або має невірний формат." } }];
}

let outputDocuments = [];

// 2. Проходимо циклом по кожному елементу (клієнти + SHAP/LIME аналітика в кінці)
rawData.forEach((item, index) => {
    let textParts = [];

    // 3. Динамічно збираємо ВСІ ключі та ВСІ значення (числа, рядки, об'єкти)
    for (const [key, value] of Object.entries(item)) {
        if (typeof value === 'object' && value !== null) {
            // Якщо всередині складний об'єкт (наприклад, блоки SHAP), перетворюємо його на текст
            textParts.push(`${key}: ${JSON.stringify(value)}`);
        } else {
            // Всі числа (Recency, Frequency, Monetary) та текст записуємо як є
            textParts.push(`${key}: ${value}`);
        }
    }

    // 4. Склеюємо всі поля об'єкта в один суцільний рядок через кому
    const completeText = textParts.join(', ');

    // 5. Формуємо правильний ітем, який n8n Vector Store з'їсть без залишку
    outputDocuments.push({
        json: {
            pageContent: completeText,
            metadata: {
                source: "blob",
                blobType: "application/json",
                line: index + 1
            }
        }
    });
});

return outputDocuments;
